def get_relevant_docs_from_knowledge(
    self, query: str, num_documents: Optional[int] = None, filters: Optional[Dict[str, Any]] = None, **kwargs
) -> Optional[List[Dict[str, Any]]]:
    """Get relevant docs from the knowledge base to answer a query.

    Args:
        query (str): The query to search for.
        num_documents (Optional[int]): Number of documents to return.
        filters (Optional[Dict[str, Any]]): Filters to apply to the search.
        **kwargs: Additional keyword arguments.

    Returns:
        Optional[List[Dict[str, Any]]]: List of relevant document dicts.
    """
    from agno.document import Document

    # Validate the filters against known valid filter keys
    if self.knowledge is not None:
        valid_filters, invalid_keys = self.knowledge.validate_filters(filters)  # type: ignore

        # Warn about invalid filter keys
        if invalid_keys:
            # type: ignore
            log_warning(f"Invalid filter keys provided: {invalid_keys}. These filters will be ignored.")
            log_info(f"Valid filter keys are: {self.knowledge.valid_metadata_filters}")  # type: ignore

            # Only use valid filters
            filters = valid_filters
            if not filters:
                log_warning("No valid filters remain after validation. Search will proceed without filters.")

    if self.retriever is not None and callable(self.retriever):
        from inspect import signature

        try:
            sig = signature(self.retriever)
            retriever_kwargs: Dict[str, Any] = {}
            if "agent" in sig.parameters:
                retriever_kwargs = {"agent": self}
            if "filters" in sig.parameters:
                retriever_kwargs["filters"] = filters
            retriever_kwargs.update({"query": query, "num_documents": num_documents, **kwargs})
            return self.retriever(**retriever_kwargs)
        except Exception as e:
            log_warning(f"Retriever failed: {e}")
            return None

    # Use knowledge base search
    #If use LangChainKnowledgeBase, then we no need to check if the vector_db is None because we have LangChainKnowledgeBase's retriever
    try:
        if self.knowledge is None or (self.knowledge.vector_db is None and self.knowledge.retriever is None):
            return None

        if num_documents is None:
            num_documents = self.knowledge.num_documents

        log_debug(f"Searching knowledge base with filters: {filters}")
        relevant_docs: List[Document] = self.knowledge.search(
            query=query, num_documents=num_documents, filters=filters
        )

        if not relevant_docs or len(relevant_docs) == 0:
            log_debug("No relevant documents found for query")
            return None

        return [doc.to_dict() for doc in relevant_docs]
    except Exception as e:
        log_warning(f"Error searching knowledge base: {e}")
        return None

async def aget_relevant_docs_from_knowledge(
    self, query: str, num_documents: Optional[int] = None, filters: Optional[Dict[str, Any]] = None, **kwargs
) -> Optional[List[Dict[str, Any]]]:
    """Get relevant documents from knowledge base asynchronously."""
    from agno.document import Document

    # Validate the filters against known valid filter keys
    if self.knowledge is not None:
        valid_filters, invalid_keys = self.knowledge.validate_filters(filters)  # type: ignore

        # Warn about invalid filter keys
        if invalid_keys:  # type: ignore
            log_warning(f"Invalid filter keys provided: {invalid_keys}. These filters will be ignored.")
            log_info(f"Valid filter keys are: {self.knowledge.valid_metadata_filters}")  # type: ignore

            # Only use valid filters
            filters = valid_filters
            if not filters:
                log_warning("No valid filters remain after validation. Search will proceed without filters.")

    if self.retriever is not None and callable(self.retriever):
        from inspect import isawaitable, signature

        try:
            sig = signature(self.retriever)
            retriever_kwargs: Dict[str, Any] = {}
            if "agent" in sig.parameters:
                retriever_kwargs = {"agent": self}
            if "filters" in sig.parameters:
                retriever_kwargs["filters"] = filters
            retriever_kwargs.update({"query": query, "num_documents": num_documents, **kwargs})
            result = self.retriever(**retriever_kwargs)

            if isawaitable(result):
                result = await result

            return result
        except Exception as e:
            log_warning(f"Retriever failed: {e}")
            return None

    # Use knowledge base search
    #If use LangChainKnowledgeBase, then we no need to check if the vector_db is None because we have LangChainKnowledgeBase's retriever
    try:
        if self.knowledge is None or (self.knowledge.vector_db is None and self.knowledge.retriever is None):
            return None

        if num_documents is None:
            num_documents = self.knowledge.num_documents

        log_debug(f"Searching knowledge base with filters: {filters}")
        relevant_docs: List[Document] = await self.knowledge.async_search(
            query=query, num_documents=num_documents, filters=filters, **kwargs
        )

        if not relevant_docs or len(relevant_docs) == 0:
            log_debug("No relevant documents found for query")
            return None

        return [doc.to_dict() for doc in relevant_docs]
    except Exception as e:
        log_warning(f"Error searching knowledge base: {e}")
        return None

    parameters: dict = {
        "type": "object",
        "properties": {
            "json_path": {
                "type": "string",
                "description": """Path to the JSON file generated by insights_selection tool.
Contains chart insights data in format:
{
  "chartPath": string,
  "insights_id": number[]
}""",
            },
            "output_type": {
                "type": "string",
                "description": "Visualization output format selection",
                "default": "html",
                "enum": [
                    "png",    # Static image format
                    "html"    # Interactive web format (recommended)
                ],
            },
        },
        "required": ["json_path"],
    }

