class Export(GlancesExport):
    """This class manages the Prometheus export module."""

    METRIC_SEPARATOR = '_'

    def __init__(self, config=None, args=None):
        """Init the Prometheus export IF."""
        super().__init__(config=config, args=args)

        # Load the Prometheus configuration file section
        self.export_enable = self.load_conf('prometheus', mandatories=['host', 'port', 'labels'], options=['prefix'])
        if not self.export_enable:
            exit('Missing PROMETHEUS config')

        # Optionals configuration keys
        if self.prefix is None:
            self.prefix = 'glances'

        if self.labels is None:
            self.labels = 'src:glances'

        # Init the metric dict
        # Perhaps a better method is possible...
        self._metric_dict = {}

        self._stats = GlancesStats()

        # Init the Prometheus Exporter
        self.init()

    def init(self):
        """Init the Prometheus Exporter"""
        try:
            start_http_server(port=int(self.port), addr=self.host)
        except Exception as e:
            logger.critical(f"Can not start Prometheus exporter on {self.host}:{self.port} ({e})")
            sys.exit(2)
        else:
            logger.info(f"Start Prometheus exporter on {self.host}:{self.port}")

    def export(self, name, columns, points):
        """Write the points to the Prometheus exporter using Gauge."""
        logger.debug(f"Export {name} stats to Prometheus exporter")

        # Remove non number stats and convert all to float (for Boolean)
        data = {str(k): float(v) for k, v in zip(columns, points) if isinstance(v, Number)}

        key_name = self._stats.get_plugin(name).get_key()

        # Write metrics to the Prometheus exporter
        for metric, value in data.items():
            labels = self.labels
            metric_name = self.prefix + self.METRIC_SEPARATOR + name + self.METRIC_SEPARATOR
            try:
                obj, stat = metric.split('.')
                metric_name += stat
                labels += f",{key_name}:{obj}"
            except ValueError:
                metric_name += metric

            # Prometheus is very sensible to the metric name
            # See: https://prometheus.io/docs/practices/naming/
            for c in ' .-/:[]':
                metric_name = metric_name.replace(c, self.METRIC_SEPARATOR)

            # Get the labels
            labels = self.parse_tags(labels)
            # Manage an internal dict between metric name and Gauge
            if metric_name not in self._metric_dict:
                self._metric_dict[metric_name] = Gauge(metric_name, "", labelnames=listkeys(labels))
            # Write the value
            if hasattr(self._metric_dict[metric_name], 'labels'):
                # Add the labels (see issue #1255)
                self._metric_dict[metric_name].labels(**labels).set(value)
            else:
                self._metric_dict[metric_name].set(value)

def _fixvalue(self, value):
    # type: (Any) -> int
    if not value:
        return 0
    if isinstance(value, str):
        value = value.split('+') if self.multi else list(value)
    if isinstance(value, list):
        y = 0
        for i in value:
            y |= 1 << self.names.index(i)
        value = y
    return int(value)

def __str__(self):
    # type: () -> str
    i = 0
    r = []
    x = int(self)
    while x:
        if x & 1:
            try:
                name = self.names[i]
            except IndexError:
                name = "?"
            r.append(name)
        i += 1
        x >>= 1
    return ("+" if self.multi else "").join(r)

def __getattr__(self, attr):
    # type: (str) -> Any
    if attr in self.__slots__:
        return super(FlagValue, self).__getattribute__(attr)
    try:
        if self.multi:
            return bool((2 ** self.names.index(attr)) & int(self))
        return all(bool((2 ** self.names.index(flag)) & int(self))
                   for flag in attr)
    except ValueError:
        if '_' in attr:
            try:
                return self.__getattr__(attr.replace('_', '-'))
            except AttributeError:
                pass
        return super(FlagValue, self).__getattribute__(attr)

def __setattr__(self, attr, value):
    # type: (str, Union[List[str], int, str]) -> None
    if attr == "value" and not isinstance(value, int):
        raise ValueError(value)
    if attr in self.__slots__:
        return super(FlagValue, self).__setattr__(attr, value)
    if attr in self.names:
        if value:
            self.value |= (2 ** self.names.index(attr))
        else:
            self.value &= ~(2 ** self.names.index(attr))
    else:
        return super(FlagValue, self).__setattr__(attr, value)

def i2repr(self,
           pkt,  # type: Optional[Packet]
           x,  # type: Any
           ):
    # type: (...) -> str
    if isinstance(x, (list, tuple)):
        return repr(type(x)(
            "None" if v is None else str(self._fixup_val(v)) for v in x
        ))
    return "None" if x is None else str(self._fixup_val(x))

def any2i(self, pkt, x):
    # type: (Optional[Packet], Any) -> Set[str]
    if not isinstance(x, (set, int)):
        raise ValueError('set expected')

    if pkt is not None:
        if isinstance(x, int):
            return self.m2i(pkt, x)
        else:
            v = self.depends_on(pkt)
            if v is not None:
                assert v in self.names, 'invalid dependency'
                these_names = self.names[v]
                s = set()
                for i in x:
                    for val in these_names.values():
                        if val.short == i:
                            s.add(i)
                            break
                    else:
                        assert False, 'Unknown flag "{}" with this dependency'.format(i)  # noqa: E501
                        continue
                return s
    if isinstance(x, int):
        return set()
    return x

def i2m(self, pkt, x):
    # type: (Optional[Packet], Optional[Set[str]]) -> int
    v = self.depends_on(pkt)
    these_names = self.names.get(v, {})

    r = 0
    if x is None:
        return r
    for flag_set in x:
        for i, val in these_names.items():
            if val.short == flag_set:
                r |= 1 << i
                break
        else:
            r |= 1 << int(flag_set[len('bit '):])
    return r

def m2i(self, pkt, x):
    # type: (Optional[Packet], int) -> Set[str]
    v = self.depends_on(pkt)
    these_names = self.names.get(v, {})

    r = set()
    i = 0
    while x:
        if x & 1:
            if i in these_names:
                r.add(these_names[i].short)
            else:
                r.add('bit {}'.format(i))
        x >>= 1
        i += 1
    return r

def i2repr(self, pkt, x):
    # type: (Optional[Packet], Set[str]) -> str
    v = self.depends_on(pkt)
    these_names = self.names.get(v, {})

    r = set()
    for flag_set in x:
        for i in these_names.values():
            if i.short == flag_set:
                r.add("{} ({})".format(i.long, i.short))
                break
        else:
            r.add(flag_set)
    return repr(r)

def format_traceback(no_tb=False):
    e, v, tb = sys.exc_info()
    # This is needed when testing chaining and cause without traceback.
    # We set `err.__traceback__ = None` in tests and apparently that makes
    # `tb` here `None´ with Python 3.11 but not with others.
    if sys.version_info < (3, 11) and no_tb:
        tb = None
    return "".join(traceback.format_exception(e, v, tb)).rstrip()

def test_chaining_without_traceback(self):
    try:
        try:
            raise ValueError("lower")
        except ValueError as err:
            raise RuntimeError("higher") from err
    except Exception as err:
        err.__traceback__ = None
        assert_equal(ErrorDetails(err).traceback, format_traceback(no_tb=True))

def test_cause_without_traceback(self):
    try:
        raise ValueError("err") from TypeError("cause")
    except ValueError as err:
        err.__traceback__ = None
        assert_equal(ErrorDetails(err).traceback, format_traceback(no_tb=True))

def count_score(prediction, ground_truth):
    """Score for counting tasks."""
    try:
        # Extract the first number from prediction
        numbers = re.findall(r'\d+', prediction)
        if not numbers:
            return 0.0
        pred_count = int(numbers[0])
        true_count = int(ground_truth)
        return 1.0 if pred_count == true_count else 0.0
    except:
        return 0.0

def numeric_match(prediction: str, ground_truth: str, tolerance: float = 0.001) -> float:
    """Check if prediction matches a numeric answer within tolerance."""
    try:
        # Extract numbers from both strings
        pred_nums = re.findall(r'-?\d+\.?\d*', extract_answer(prediction))
        truth_nums = re.findall(r'-?\d+\.?\d*', ground_truth)

        if not pred_nums or not truth_nums:
            # Fall back to exact match if no numbers found
            return exact_match(prediction, ground_truth)

        pred_num = float(pred_nums[0])
        truth_num = float(truth_nums[0])

        return 1.0 if abs(pred_num - truth_num) < tolerance else 0.0
    except:
        # Fall back to exact match if parsing fails
        return exact_match(prediction, ground_truth)

def math_accuracy(prediction: str, ground_truth: str, tolerance: float = 0.001) -> float:
    """Evaluate mathematical answer accuracy."""
    try:
        pred_num = float(extract_number(prediction))
        truth_num = float(extract_number(ground_truth))
        return 1.0 if abs(pred_num - truth_num) < tolerance else 0.0
    except:
        # If not numeric, do exact match
        return 1.0 if normalize_text(prediction) == normalize_text(ground_truth) else 0.0

def get_model_info(self) -> dict:
    """Method to get Hugging Face model information for experiment reproducibility."""

    def get_model_num_params(model) -> int:
        if hasattr(model, "num_parameters"):
            return model.num_parameters()
        if hasattr(model, "parameters"):
            return sum(p.numel() for p in model.parameters())
        else:
            return -1

    def get_model_dtype(model) -> str:
        if hasattr(model, "dtype"):
            return model.dtype
        else:
            return ""

    def get_model_sha(pretrained: str, revision: str) -> str:
        try:
            model_info = HfApi().model_info(repo_id=pretrained, revision=revision)
            return model_info.sha
        except Exception as e:
            eval_logger.debug(
                f"Failed to get model SHA for {pretrained} at revision {revision}. Error: {e}"
            )
            return ""

    model_info = {
        "model_num_parameters": get_model_num_params(self._model),
        "model_dtype": get_model_dtype(self._model),
        "model_revision": self.revision,
        "model_sha": get_model_sha(self.pretrained, self.revision),
    }
    if self.peft:
        model_info["peft_sha"] = get_model_sha(self.peft, self.revision)
    if self.delta:
        model_info["delta_sha"] = get_model_sha(self.delta, self.revision)
    return model_info

def _build_date_trunc(args: t.List[exp.Expression]) -> exp.Expression:
    a0, a1 = seq_get(args, 0), seq_get(args, 1)

    def _is_unit_like(e: exp.Expression | None) -> bool:
        if not (isinstance(e, exp.Literal) and e.is_string):
            return False
        text = e.this
        return not any(ch.isdigit() for ch in text)

    # Determine which argument is the unit
    unit, this = a0, a1 if _is_unit_like(a0) else a1, a0

    return exp.TimestampTrunc(this=this, unit=unit)

