def _direct_capture(self, event: BaseTelemetryEvent) -> None:
	"""
	Should not be thread blocking because posthog magically handles it
	"""
	if self._posthog_client is None:
		return

	try:
		self._posthog_client.capture(
			self.user_id,
			event.name,
			{**event.properties, **POSTHOG_EVENT_SETTINGS},
		)
	except Exception as e:
		logger.error(f'Failed to send telemetry event {event.name}: {e}')

def are_images_identical(img_path1: str, img_path2: str) -> bool:
	"""Check if two images are identical by comparing their content."""
	try:
		with Image.open(img_path1) as img1, Image.open(img_path2) as img2:
			# Convert to same format for comparison
			if img1.mode != img2.mode:
				img1 = img1.convert('RGB')
				img2 = img2.convert('RGB')

			# Compare sizes first (quick check)
			if img1.size != img2.size:
				return False

			# Compare pixel data
			return list(img1.getdata()) == list(img2.getdata())
	except Exception as e:
		logger.warning(f'Failed to compare images {img_path1} and {img_path2}: {e}')
		return False

def _convert_simple_xpath_to_css_selector(xpath: str) -> str:
	"""Converts simple XPath expressions to CSS selectors."""
	if not xpath:
		return ''

	# Remove leading slash if present
	xpath = xpath.lstrip('/')

	# Split into parts
	parts = xpath.split('/')
	css_parts = []

	for part in parts:
		if not part:
			continue

		# Handle custom elements with colons by escaping them
		if ':' in part and '[' not in part:
			base_part = part.replace(':', r'\:')
			css_parts.append(base_part)
			continue

		# Handle index notation [n]
		if '[' in part:
			base_part = part[: part.find('[')]
			# Handle custom elements with colons in the base part
			if ':' in base_part:
				base_part = base_part.replace(':', r'\:')
			index_part = part[part.find('[') :]

			# Handle multiple indices
			indices = [i.strip('[]') for i in index_part.split(']')[:-1]]

			for idx in indices:
				try:
					# Handle numeric indices
					if idx.isdigit():
						index = int(idx) - 1
						base_part += f':nth-of-type({index + 1})'
					# Handle last() function
					elif idx == 'last()':
						base_part += ':last-of-type'
					# Handle position() functions
					elif 'position()' in idx:
						if '>1' in idx:
							base_part += ':nth-of-type(n+2)'
				except ValueError:
					continue

			css_parts.append(base_part)
		else:
			css_parts.append(part)

	base_selector = ' > '.join(css_parts)
	return base_selector

