def _direct_capture(self, event: BaseTelemetryEvent) -> None:
	"""
	Should not be thread blocking because posthog magically handles it
	"""
	if self._posthog_client is None:
		return

	try:
		self._posthog_client.capture(
			self.user_id,
			event.name,
			{**event.properties, **POSTHOG_EVENT_SETTINGS},
		)
	except Exception as e:
		logger.error(f'Failed to send telemetry event {event.name}: {e}')

def are_images_identical(img_path1: str, img_path2: str) -> bool:
	"""Check if two images are identical by comparing their content."""
	try:
		with Image.open(img_path1) as img1, Image.open(img_path2) as img2:
			# Convert to same format for comparison
			if img1.mode != img2.mode:
				img1 = img1.convert('RGB')
				img2 = img2.convert('RGB')

			# Compare sizes first (quick check)
			if img1.size != img2.size:
				return False

			# Compare pixel data
			return list(img1.getdata()) == list(img2.getdata())
	except Exception as e:
		logger.warning(f'Failed to compare images {img_path1} and {img_path2}: {e}')
		return False

def _get_client_params(self) -> dict[str, Any]:
	"""Prepare client parameters dictionary for Bedrock."""
	client_params: dict[str, Any] = {}

	if self.session:
		credentials = self.session.get_credentials()
		client_params.update(
			{
				'aws_access_key': credentials.access_key,
				'aws_secret_key': credentials.secret_key,
				'aws_session_token': credentials.token,
				'aws_region': self.session.region_name,
			}
		)
	else:
		# Use individual credentials
		if self.aws_access_key:
			client_params['aws_access_key'] = self.aws_access_key
		if self.aws_secret_key:
			client_params['aws_secret_key'] = self.aws_secret_key
		if self.aws_region:
			client_params['aws_region'] = self.aws_region
		if self.aws_session_token:
			client_params['aws_session_token'] = self.aws_session_token

	# Add optional parameters
	if self.max_retries:
		client_params['max_retries'] = self.max_retries
	if self.default_headers:
		client_params['default_headers'] = self.default_headers
	if self.default_query:
		client_params['default_query'] = self.default_query

	return client_params

